import { createHash } from "node:crypto";
import { blocksToHtml, normalizeArticleHtml, plainTextToHtml } from "./rich-text.mjs";

// Only compare editorial fields. Block IDs are regenerated by some editors.
export function publishedContentHash(article) {
  const body = article.bodyHtml || normalizeArticleHtml(blocksToHtml(article.blocks) || plainTextToHtml(article.body));
  const fields = [article.title, article.spot, body, article.category, article.author,
    article.heroImage, article.imageAlt, article.videoUrl, article.sourceName, article.sourceUrl,
    article.agencySourceId, article.agencyExternalId, article.agencyCredit, article.correctionNote];
  return createHash("sha256").update(JSON.stringify(fields.map(value => value ?? ""))).digest("hex");
}

const migrationKey = "_article_publication_dates_v1";

export function ensurePublicationDates(db, postgres) {
  if (db.prepare("SELECT 1 FROM content_items WHERE key=?").get(migrationKey)) return;
  db.transaction(() => {
    // The unique key serializes concurrent workers. A failed migration rolls it back.
    const claim = db.prepare("INSERT INTO content_items(key,value,updated_at) VALUES (?,'true',?) ON CONFLICT(key) DO NOTHING").run(migrationKey, Date.now());
    if (!claim.changes) return;
    if (postgres) {
      db.exec("ALTER TABLE articles ADD COLUMN IF NOT EXISTS content_modified_at BIGINT, ADD COLUMN IF NOT EXISTS published_content_hash TEXT");
    } else {
      const columns = db.prepare("PRAGMA table_info(articles)").all();
      if (!columns.some(column => column.name === "content_modified_at")) db.exec("ALTER TABLE articles ADD COLUMN content_modified_at INTEGER");
      if (!columns.some(column => column.name === "published_content_hash")) db.exec("ALTER TABLE articles ADD COLUMN published_content_hash TEXT");
    }
    backfillPublicationDates(db);
  })();
}

function backfillPublicationDates(db) {
  // A generic updated_at or import time is not evidence of an editorial update.
  const revisions = db.prepare("SELECT id,article_id,version,snapshot,created_at FROM article_revisions WHERE reason='save' AND id>? ORDER BY id LIMIT 128");
  const histories = new Map();
  let cursor = 0;
  for (;;) {
    const rows = revisions.all(cursor);
    if (!rows.length) break;
    for (const row of rows) {
      cursor = row.id;
      let article;
      try { article = JSON.parse(row.snapshot); } catch { continue; }
      if (article?.status !== "published" || !Number.isFinite(article.publishedAt)) continue;
      const hash = publishedContentHash(article);
      const previous = histories.get(row.article_id);
      // Consecutive saved versions establish exactly which save changed the content.
      const changed = previous?.version === row.version - 1 && previous.hash !== hash;
      histories.set(row.article_id, {
        first: previous?.first ?? article.publishedAt, hash, version: row.version,
        modified: changed ? Number(row.created_at) : previous?.modified ?? null,
      });
    }
  }
  const update = db.prepare("UPDATE articles SET published_at=CASE WHEN published_at IS NULL OR published_at>? THEN ? ELSE published_at END,content_modified_at=?,published_content_hash=CASE WHEN status='published' THEN NULL ELSE ? END WHERE id=?");
  for (const [id, item] of histories) update.run(item.first, item.first, item.modified, item.hash, id);

  const corrections = db.prepare("SELECT article_id,note,created_at FROM workflow_events WHERE action='correction' ORDER BY article_id,id").all();
  const correction = db.prepare("UPDATE articles SET content_modified_at=? WHERE id=? AND published_at<=? AND (content_modified_at IS NULL OR content_modified_at<?)");
  let lastArticle, lastNote;
  for (const row of corrections) {
    if (lastArticle !== row.article_id || lastNote !== row.note) correction.run(row.created_at, row.article_id, row.created_at, row.created_at);
    lastArticle = row.article_id;
    lastNote = row.note;
  }
}
